class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def ladoos(root: TreeNode, home: int, K: int) -> int:
    def dfs(node, parent_map):
        if node:
            if node.val == home:
                start_node = node
            if node.left:
                parent_map[node.left] = node
            if node.right:
                parent_map[node.right] = node
            left_start, left_sum = dfs(node.left, parent_map)
            right_start, right_sum = dfs(node.right, parent_map)
            if 'start_node' in locals():
                return start_node, node.val
            if left_start:
                return left_start, left_sum + node.val
            if right_start:
                return right_start, right_sum + node.val
            return None, 0

    def collect_ladoos(node, parent_map, dist, visited):
        if not node or dist < 0 or node in visited:
            return 0
        visited.add(node)
        return (node.val +
                collect_ladoos(node.left, parent_map, dist - 1, visited) +
                collect_ladoos(node.right, parent_map, dist - 1, visited) +
                collect_ladosos(parent_map.get(node), parent_map, dist - 1, visited))

    parent_map = {}
    start_node, _ = dfs(root, parent_map)
    return collect_ladoos(start_node, parent_map, K, set())
